inline constexpr std::uint32_t kInputProfileRevision = 2;
inline constexpr std::uint8_t kKeyboardReportId = 1;
inline constexpr std::uint8_t kConsumerReportId = 2;
inline constexpr std::size_t kKeyboardUsageCount = 224;
inline constexpr std::size_t kConsumerKeyCount = 32;
using KeyboardState = std::array<std::uint8_t, 1 + kKeyboardUsageCount / 8>;
using ConsumerState = std::array<std::uint16_t, kConsumerKeyCount>;
using MouseState = std::array<std::uint8_t, 4>;
inline constexpr std::size_t kKeyboardWireSize = 1 + KeyboardState{}.size();
inline constexpr std::size_t kConsumerWireSize = 1 + 2 * kConsumerKeyCount;

